// Generated by Cypress Author on 2026-10-12
//
// Deterministic regression coverage for the animated video-thumbnail hover
// lifecycle (spec: .kiro/specs/video-thumbnail-hover-hardening).
//
// The feature requests a static video poster, and — only once that poster has
// actually loaded in the browser and the tile is the grid's single
// latest-active preview — requests a looping animated WebP and shows frame
// progress. These tests force each lifecycle edge with controlled transform
// and job responses plus delayed image delivery, so correctness never depends
// on wall-clock timing. Mock image URLs are served with real JPEG bytes so the
// browser's genuine load / error events fire; a placeholder string body would
// never produce a successful onLoad and could not prove the poster gate.
//
// Pointer hover is driven with real PointerEvents dispatched as `pointerover`
// / `pointerout` on the thumbnail element. React derives its declarative
// `onPointerEnter` / `onPointerLeave` from the bubbling `pointerover` /
// `pointerout` native events, so those are the events a hover must simulate.
// Cypress subjects are unsafe after `.trigger()`, so every helper reacquires
// the element it operates on.

import { isRecord } from "../tasks/narrow.js";
import { jobIdFrom, waitForJob } from "../support/jobs.js";
import { rememberPreparedObject } from "../support/preparedObject.js";

// Two distinct videos let us exercise latest-active supersession (A -> B).
const VIDEO_A = "cypress/fixtures/testFiles/WIN_20251119_00_55_14_Pro.mp4";
const VIDEO_B = "cypress/fixtures/testFiles/WIN_20251119_00_55_32_Pro.mp4";
const IMAGE = "cypress/fixtures/testFiles/WIN_20260102_21_30_21_Pro.jpg";
// Fixture path (relative to cypress/fixtures) streamed verbatim as the bytes
// for every mocked poster/animation URL, so the browser fires a genuine load
// event with a decodable image (positive naturalWidth).
const IMAGE_FIXTURE = "testFiles/WIN_20260102_21_30_21_Pro.jpg";

// Shared extended timeout. Uploads commit through a 202 job receipt and the
// list query is invalidated asynchronously, so rows can take noticeably longer
// than the 4s default to reach the DOM.
const LONG = 20000;

function fileNameOf(path: string): string {
  return path.slice(path.lastIndexOf("/") + 1);
}

function namedFixture(
  path: string,
  marker: string,
): { contents: string; fileName: string } {
  const base = fileNameOf(path);
  const dot = base.lastIndexOf(".");
  const stem = dot >= 0 ? base.slice(0, dot) : base;
  const ext = dot >= 0 ? base.slice(dot) : "";
  return { contents: path, fileName: `${stem}-${marker}${ext}` };
}

function objectsGrid() {
  return cy.get("[data-cy='dStorage_objects']:visible", { timeout: LONG });
}

// Reacquire the committed tile by its exact file name, retrying with the
// extended timeout until the asynchronously invalidated list renders it.
function tile(fileName: string) {
  return cy.contains("[data-cy='dStorage_item']", fileName, { timeout: LONG });
}

function previewOf(
  interceptions: ReadonlyArray<{ request: { body?: unknown } }>,
  preview: string,
  sourceIncludes: string,
) {
  return interceptions.filter(function (interception) {
    const body: unknown = interception.request.body;
    return (
      isRecord(body) &&
      body.preview === preview &&
      typeof body.sourceKey === "string" &&
      body.sourceKey.includes(sourceIncludes)
    );
  });
}

function signInAndOpenDrive() {
  cy.signInAsUser(0);
  cy.intercept({
    method: "GET",
    url: /\/api\/storage\/buckets\/[^/]+\/objects\?/,
  }).as("listObjects");
  cy.intercept({
    method: "POST",
    url: /\/api\/storage\/buckets\/[^/]+\/objects\/presign(\?|$)/,
  }).as("presignObject");
  cy.intercept({
    method: "POST",
    url: /\/api\/storage\/buckets\/[^/]+\/objects\/commit$/,
  }).as("commitObject");
  cy.visit("/drive/mine");
  cy.waitForClerkLoaded();
  objectsGrid().should("exist");
  cy.wait("@listObjects");
}

function rememberPresign() {
  cy.wait("@presignObject", { timeout: 60000 }).then((interception) => {
    expect(interception.response?.statusCode).to.eq(202);
    return waitForJob(jobIdFrom(interception.response?.body)).then((job) => {
      expect(job.status).to.eq("completed");
      return rememberPreparedObject(job.result);
    });
  });
}

function waitForCommit() {
  cy.wait("@commitObject", { timeout: 60000 }).then((interception) => {
    expect(interception.response?.statusCode).to.eq(202);
    return waitForJob(jobIdFrom(interception.response?.body)).then((job) => {
      expect(job.status).to.eq("completed");
    });
  });
}

function uploadThroughDialog(files: readonly Cypress.FileReference[]) {
  cy.get("[data-cy='dStorage_upload']").click();
  cy.get("[role='dialog'] input[type='file']").selectFile([...files], {
    force: true,
  });
  cy.get("[data-cy='dStorage_upload_submit']").click();
  for (let i = 0; i < files.length; i++) {
    rememberPresign();
  }
  for (let i = 0; i < files.length; i++) {
    waitForCommit();
  }
  cy.get("[role='dialog']", { timeout: LONG }).should("not.exist");
  // The commit receipt is a 202 job; the list query is invalidated
  // asynchronously afterwards. Treat the exact uploaded name appearing in the
  // DOM — not merely the list request firing — as proof the row is renderable.
  cy.wait("@listObjects", { timeout: LONG });
  for (const file of files) {
    const name =
      typeof file === "object" && file !== null && "fileName" in file
        ? (file as { fileName: string }).fileName
        : fileNameOf(file as string);
    objectsGrid().should("contain", name);
  }
}

function openTiles() {
  cy.get("[data-cy='dStorage_view_options']").click();
  cy.get("[data-cy='dStorage_view_tiles']").click();
}

// React's declarative onPointerEnter / onPointerLeave are synthesized from the
// bubbling pointerover / pointerout native events, so hover is simulated with
// those. Events are built as real PointerEvents (eventConstructor) and the
// element is reacquired first because Cypress subjects are unsafe after
// `.trigger()`.
function hoverEnter(fileName: string) {
  tile(fileName)
    .find("[data-cy='dStorage_thumbnail']")
    .trigger("pointerover", {
      eventConstructor: "PointerEvent",
      bubbles: true,
    });
}

function hoverLeave(fileName: string) {
  tile(fileName)
    .find("[data-cy='dStorage_thumbnail']")
    .trigger("pointerout", { eventConstructor: "PointerEvent", bubbles: true });
}

// A poster/animation image has genuinely loaded only when the current URL is
// shown AND the browser reports a decoded image: complete === true with a
// positive naturalWidth. `src` presence alone, or a broken (complete but
// zero-size) image, must not count as loaded.
function assertImageLoaded(
  fileName: string,
  selector: string,
  urlPart: string,
) {
  tile(fileName)
    .find(`[data-cy='${selector}']`, { timeout: LONG })
    .should("have.attr", "src")
    .and("include", urlPart);
  tile(fileName)
    .find(`[data-cy='${selector}']`, { timeout: LONG })
    .should((element) => {
      const image = element[0] as HTMLImageElement;
      expect(image.currentSrc, "image currentSrc").to.include(urlPart);
      expect(image.complete, "image complete").to.eq(true);
      expect(image.naturalWidth, "image naturalWidth").to.be.greaterThan(0);
    });
}

// Serve a real decodable JPEG for a mocked thumbnail URL so the browser
// produces a genuine load event with a positive naturalWidth. The bytes come
// from a Cypress fixture: returning a hand-built Buffer body corrupts the
// payload (the browser decodes it to naturalWidth 0, which the poster gate
// correctly treats as broken), whereas the `fixture` StaticResponse streams
// the file verbatim with the right binary encoding. `delayMs` separates
// "server returned a URL" from "the image actually finished loading", the
// exact gap the poster gate must respect.
function serveImage(path: string, delayMs?: number) {
  cy.intercept("GET", path, {
    fixture: IMAGE_FIXTURE,
    ...(delayMs ? { delay: delayMs } : {}),
  });
}

// Route a transform POST that belongs to one of the test-owned source keys.
// Unrelated sources (existing objects left over in the account) are passed
// through to the real backend untouched so they are never misclassified as a
// test tile. `owners` maps a source-key substring to the poster/animation job
// ids that source should receive.
function routeTransform(
  owners: ReadonlyArray<{
    includes: string;
    posterJobId: string;
    animationJobId?: string;
  }>,
  alias: string,
) {
  cy.intercept("POST", "/api/images/transform", (req) => {
    const body: unknown = req.body;
    if (
      !isRecord(body) ||
      typeof body.preview !== "string" ||
      typeof body.sourceKey !== "string"
    ) {
      throw new Error("transform request is missing preview/source");
    }
    const sourceKey = body.sourceKey;
    const owner = owners.find((candidate) =>
      sourceKey.includes(candidate.includes),
    );
    if (!owner) {
      // Not a test-owned tile: let the real backend answer it.
      req.continue();
      return;
    }
    if (body.preview === "animation") {
      if (!owner.animationJobId) {
        throw new Error(`unexpected animation request for ${owner.includes}`);
      }
      req.reply({
        statusCode: 202,
        body: { jobId: owner.animationJobId, status: "pending" },
      });
      return;
    }
    req.reply({
      statusCode: 202,
      body: { jobId: owner.posterJobId, status: "pending" },
    });
  }).as(alias);
}

// A completed-job StaticResponse whose body carries the result URL. Returning
// a StaticResponse (statusCode + body) is required for BOTH `cy.intercept(url,
// response)` and `req.reply(response)`: a bare job object would be read as a
// StaticResponse with unknown keys and yield an empty 200 body.
function completedPosterJob(jobId: string, path: string) {
  return {
    statusCode: 200,
    body: {
      jobId,
      status: "completed",
      httpStatus: 200,
      result: {
        url: `${Cypress.config("baseUrl")}${path}`,
        contentType: "image/jpeg",
      },
    },
  };
}

describe("video thumbnail hover", () => {
  beforeEach(() => {
    cy.viewport(1440, 900);
  });

  // Task 1: poster-load gating.
  it("hovers a still-loading video poster → no animation request fires before the poster image loads", () => {
    cy.uniqueRecordName("gate").then((marker) => {
      const video = namedFixture(VIDEO_A, marker);
      const posterJobId = "a1111111-1111-4111-8111-111111111111";
      const animationJobId = "a2222222-2222-4222-8222-222222222222";
      const posterPath = "/mock-thumbs/gate-poster.jpg";

      signInAndOpenDrive();
      uploadThroughDialog([video]);

      // Poster image arrives slowly so there is a window where the server has
      // returned a URL but the browser has not finished loading it.
      serveImage(posterPath, 1500);
      routeTransform(
        [{ includes: video.fileName, posterJobId, animationJobId }],
        "transform",
      );
      cy.intercept(
        "GET",
        `/api/jobs/${posterJobId}`,
        completedPosterJob(posterJobId, posterPath),
      );

      openTiles();
      tile(video.fileName).scrollIntoView();

      // Hover while the poster is still loading. The animation must not start.
      hoverEnter(video.fileName);
      cy.get("@transform.all").should((interceptions) => {
        expect(
          previewOf(interceptions, "animation", video.fileName),
          "no animation before poster load",
        ).to.have.length(0);
      });

      // Once the poster image genuinely loads and the tile is still active,
      // the animation request is allowed.
      assertImageLoaded(video.fileName, "dStorage_thumbnail_image", posterPath);
      cy.get("@transform.all", { timeout: LONG }).should((interceptions) => {
        expect(
          previewOf(interceptions, "animation", video.fileName).length,
          "animation requested only after poster load",
        ).to.be.greaterThan(0);
      });
    });
  });

  // Task 1: leave before load.
  it("pointer leaves before the poster loads → the delayed load does not start animation", () => {
    cy.uniqueRecordName("leave").then((marker) => {
      const video = namedFixture(VIDEO_A, marker);
      const posterJobId = "b1111111-1111-4111-8111-111111111111";
      const animationJobId = "b2222222-2222-4222-8222-222222222222";
      const posterPath = "/mock-thumbs/leave-poster.jpg";

      signInAndOpenDrive();
      uploadThroughDialog([video]);
      serveImage(posterPath, 2000);
      routeTransform(
        [{ includes: video.fileName, posterJobId, animationJobId }],
        "transform",
      );
      cy.intercept(
        "GET",
        `/api/jobs/${posterJobId}`,
        completedPosterJob(posterJobId, posterPath),
      );

      openTiles();
      tile(video.fileName).scrollIntoView();
      hoverEnter(video.fileName);
      hoverLeave(video.fileName);

      // Let the delayed poster finish and settle, then confirm no animation.
      assertImageLoaded(video.fileName, "dStorage_thumbnail_image", posterPath);
      cy.get("@transform.all").should((interceptions) => {
        expect(
          previewOf(interceptions, "animation", video.fileName),
          "leave-before-load never starts animation",
        ).to.have.length(0);
      });
    });
  });

  // Task 2 + Task 3: one-frame latest-active arbitration and superseded cancellation.
  it("rapid A → B hover within one frame → only the latest tile generates and polls", () => {
    cy.uniqueRecordName("latest").then((marker) => {
      const a = namedFixture(VIDEO_A, marker);
      const b = namedFixture(VIDEO_B, marker);
      const posterA = "/mock-thumbs/latest-poster-a.jpg";
      const posterB = "/mock-thumbs/latest-poster-b.jpg";
      const jobPosterA = "c1111111-1111-4111-8111-111111111111";
      const jobPosterB = "c2222222-2222-4222-8222-222222222222";
      const jobAnimA = "c3333333-3333-4333-8333-333333333333";
      const jobAnimB = "c4444444-4444-4444-8444-444444444444";
      let aAnimPolls = 0;
      let bAnimPolls = 0;

      signInAndOpenDrive();
      uploadThroughDialog([a, b]);
      serveImage(posterA);
      serveImage(posterB);
      routeTransform(
        [
          {
            includes: a.fileName,
            posterJobId: jobPosterA,
            animationJobId: jobAnimA,
          },
          {
            includes: b.fileName,
            posterJobId: jobPosterB,
            animationJobId: jobAnimB,
          },
        ],
        "transform",
      );

      cy.intercept("GET", /\/api\/jobs\//, (req) => {
        const jobId = req.url.split("/").pop() ?? "";
        if (jobId === jobPosterA || jobId === jobPosterB) {
          req.reply(
            completedPosterJob(jobId, jobId === jobPosterA ? posterA : posterB),
          );
          return;
        }
        if (jobId === jobAnimA) {
          aAnimPolls += 1;
          req.reply({
            statusCode: 200,
            body: {
              jobId,
              status: "running",
              progress: { phase: "frames", completed: 2, total: 7 },
            },
          });
          return;
        }
        if (jobId === jobAnimB) {
          bAnimPolls += 1;
          req.reply({
            statusCode: 200,
            body: {
              jobId,
              status: "running",
              progress: { phase: "frames", completed: 4, total: 7 },
            },
          });
          return;
        }
        req.continue();
      }).as("job");

      openTiles();
      tile(a.fileName).scrollIntoView();
      tile(b.fileName).scrollIntoView();

      // Both posters must genuinely load before either tile can animate.
      assertImageLoaded(a.fileName, "dStorage_thumbnail_image", posterA);
      assertImageLoaded(b.fileName, "dStorage_thumbnail_image", posterB);

      // Enter A then B within the same browser turn, before the coalescing
      // frame boundary; B is the latest candidate when the frame fires.
      hoverEnter(a.fileName);
      hoverEnter(b.fileName);

      // Only B shows progress; A never does.
      tile(b.fileName)
        .find("[role='progressbar']", { timeout: LONG })
        .should("have.attr", "aria-valuenow", "4");
      tile(a.fileName).find("[role='progressbar']").should("not.exist");

      // Record A's poll count at the arbitration boundary, let B advance, and
      // prove A performed no polls after being superseded in the same frame.
      cy.then(() => {
        const aAtBoundary = aAnimPolls;
        return cy
          .wrap(null)
          .then(() => {
            tile(b.fileName)
              .find("[role='progressbar']")
              .should("have.attr", "aria-valuenow", "4");
          })
          .then(() => {
            expect(bAnimPolls, "B keeps polling").to.be.greaterThan(0);
            expect(aAnimPolls, "A never polls after being superseded").to.eq(
              aAtBoundary,
            );
          });
      });

      cy.get("@transform.all").should((interceptions) => {
        expect(
          previewOf(interceptions, "animation", b.fileName).length,
          "B requested an animation",
        ).to.be.greaterThan(0);
      });
    });
  });

  // Task 3: post-start supersession stops the previous tile's polling.
  it("A starts polling then B becomes active → A stops polling and only B shows progress", () => {
    cy.uniqueRecordName("supersede").then((marker) => {
      const a = namedFixture(VIDEO_A, marker);
      const b = namedFixture(VIDEO_B, marker);
      const posterA = "/mock-thumbs/supersede-poster-a.jpg";
      const posterB = "/mock-thumbs/supersede-poster-b.jpg";
      const jobPosterA = "f1111111-1111-4111-8111-111111111111";
      const jobPosterB = "f2222222-2222-4222-8222-222222222222";
      const jobAnimA = "f3333333-3333-4333-8333-333333333333";
      const jobAnimB = "f4444444-4444-4444-8444-444444444444";
      let aAnimPolls = 0;
      let bAnimPolls = 0;

      signInAndOpenDrive();
      uploadThroughDialog([a, b]);
      serveImage(posterA);
      serveImage(posterB);
      routeTransform(
        [
          {
            includes: a.fileName,
            posterJobId: jobPosterA,
            animationJobId: jobAnimA,
          },
          {
            includes: b.fileName,
            posterJobId: jobPosterB,
            animationJobId: jobAnimB,
          },
        ],
        "transform",
      );
      cy.intercept("GET", /\/api\/jobs\//, (req) => {
        const jobId = req.url.split("/").pop() ?? "";
        if (jobId === jobPosterA || jobId === jobPosterB) {
          req.reply(
            completedPosterJob(jobId, jobId === jobPosterA ? posterA : posterB),
          );
          return;
        }
        if (jobId === jobAnimA) {
          aAnimPolls += 1;
          req.reply({
            statusCode: 200,
            body: {
              jobId,
              status: "running",
              progress: { phase: "frames", completed: 3, total: 9 },
            },
          });
          return;
        }
        if (jobId === jobAnimB) {
          bAnimPolls += 1;
          req.reply({
            statusCode: 200,
            body: {
              jobId,
              status: "running",
              progress: { phase: "frames", completed: 6, total: 9 },
            },
          });
          return;
        }
        req.continue();
      }).as("job");

      openTiles();
      tile(a.fileName).scrollIntoView();
      tile(b.fileName).scrollIntoView();
      assertImageLoaded(a.fileName, "dStorage_thumbnail_image", posterA);
      assertImageLoaded(b.fileName, "dStorage_thumbnail_image", posterB);

      // Hover A alone and let it start polling and showing progress.
      hoverEnter(a.fileName);
      tile(a.fileName)
        .find("[role='progressbar']", { timeout: LONG })
        .should("have.attr", "aria-valuenow", "3");

      // Now move to B after A has started.
      hoverLeave(a.fileName);
      hoverEnter(b.fileName);

      // B owns progress; A's progress disappears.
      tile(b.fileName)
        .find("[role='progressbar']", { timeout: LONG })
        .should("have.attr", "aria-valuenow", "6");
      tile(a.fileName).find("[role='progressbar']").should("not.exist");

      // After the cancellation boundary A must not poll again while B advances.
      cy.then(() => {
        const aAtBoundary = aAnimPolls;
        return cy
          .wrap(null)
          .then(() => {
            tile(b.fileName)
              .find("[role='progressbar']")
              .should("have.attr", "aria-valuenow", "6");
          })
          .then(() => {
            expect(bAnimPolls, "B keeps polling").to.be.greaterThan(0);
            expect(aAnimPolls, "A stops polling after supersession").to.eq(
              aAtBoundary,
            );
          });
      });
    });
  });

  // Task 3: successful animation data is reusable without a second transform.
  it("completes an animation, leaves, re-hovers → cached animation reused with no second transform", () => {
    cy.uniqueRecordName("cache").then((marker) => {
      const video = namedFixture(VIDEO_A, marker);
      const posterPath = "/mock-thumbs/cache-poster.jpg";
      const animationPath = "/mock-thumbs/cache-animation.jpg";
      const posterJobId = "91111111-1111-4111-8111-111111111111";
      const animationJobId = "92222222-2222-4222-8222-222222222222";

      signInAndOpenDrive();
      uploadThroughDialog([video]);
      serveImage(posterPath);
      serveImage(animationPath);
      routeTransform(
        [{ includes: video.fileName, posterJobId, animationJobId }],
        "transform",
      );
      cy.intercept("GET", /\/api\/jobs\//, (req) => {
        const jobId = req.url.split("/").pop() ?? "";
        if (jobId === posterJobId) {
          req.reply(completedPosterJob(posterJobId, posterPath));
          return;
        }
        if (jobId === animationJobId) {
          req.reply(completedPosterJob(animationJobId, animationPath));
          return;
        }
        req.continue();
      }).as("job");

      openTiles();
      tile(video.fileName).scrollIntoView();
      assertImageLoaded(video.fileName, "dStorage_thumbnail_image", posterPath);

      // Hover: animation generates and the animated frame appears.
      hoverEnter(video.fileName);
      assertImageLoaded(
        video.fileName,
        "dStorage_thumbnail_animation",
        animationPath,
      );
      cy.get("@transform.all").should((interceptions) => {
        expect(
          previewOf(interceptions, "animation", video.fileName).length,
          "animation requested once",
        ).to.eq(1);
      });

      // Leave: the poster returns (animation hidden on an inactive tile).
      hoverLeave(video.fileName);
      tile(video.fileName)
        .find("[data-cy='dStorage_thumbnail_image']", { timeout: LONG })
        .should("have.attr", "src")
        .and("include", posterPath);
      tile(video.fileName)
        .find("[data-cy='dStorage_thumbnail_animation']")
        .should("not.exist");

      // Re-hover: the cached animation reappears with no second transform POST.
      hoverEnter(video.fileName);
      assertImageLoaded(
        video.fileName,
        "dStorage_thumbnail_animation",
        animationPath,
      );
      cy.get("@transform.all").should((interceptions) => {
        expect(
          previewOf(interceptions, "animation", video.fileName).length,
          "re-hover reuses cache (no second animation transform)",
        ).to.eq(1);
      });
    });
  });

  // Task 4: quiet failure fallback for a failed animation job.
  it("animation job fails → the poster stays and no error is shown", () => {
    cy.uniqueRecordName("fail").then((marker) => {
      const video = namedFixture(VIDEO_A, marker);
      const posterPath = "/mock-thumbs/fail-poster.jpg";
      const posterJobId = "d1111111-1111-4111-8111-111111111111";
      const animationJobId = "d2222222-2222-4222-8222-222222222222";

      signInAndOpenDrive();
      uploadThroughDialog([video]);
      serveImage(posterPath);
      routeTransform(
        [{ includes: video.fileName, posterJobId, animationJobId }],
        "transform",
      );
      cy.intercept(
        "GET",
        `/api/jobs/${posterJobId}`,
        completedPosterJob(posterJobId, posterPath),
      );
      // The animation render times out on the backend (504-style failure).
      cy.intercept("GET", `/api/jobs/${animationJobId}`, {
        statusCode: 200,
        body: {
          jobId: animationJobId,
          status: "failed",
          httpStatus: 504,
          error: { message: "Image processing timed out" },
        },
      });

      openTiles();
      tile(video.fileName).scrollIntoView();
      assertImageLoaded(video.fileName, "dStorage_thumbnail_image", posterPath);
      hoverEnter(video.fileName);

      // After the animation fails, the poster remains and no progress persists.
      tile(video.fileName)
        .find("[data-cy='dStorage_thumbnail_image']", { timeout: LONG })
        .should("have.attr", "src")
        .and("include", posterPath);
      tile(video.fileName).find("[role='progressbar']").should("not.exist");
      tile(video.fileName)
        .find("[data-cy='dStorage_thumbnail_animation']")
        .should("not.exist");
    });
  });

  // Task 4: non-video isolation.
  it("image and PDF tiles never request an animation", () => {
    cy.uniqueRecordName("isolate").then((marker) => {
      const image = namedFixture(IMAGE, marker);
      const pdf = {
        contents: Cypress.Buffer.from(
          "%PDF-1.1\n1 0 obj<<>>endobj\ntrailer<<>>\n%%EOF\n",
        ),
        fileName: `brief-${marker}.pdf`,
        mimeType: "application/pdf",
      };
      const imagePath = "/mock-thumbs/isolate-image.jpg";
      const imageJobId = "e1111111-1111-4111-8111-111111111111";

      signInAndOpenDrive();
      uploadThroughDialog([image, pdf]);
      serveImage(imagePath);

      // Image gets a completed poster; PDF transform fails (fallback). Neither
      // owner declares an animation job, so an animation request would throw.
      cy.intercept("POST", "/api/images/transform", (req) => {
        const body: unknown = req.body;
        if (
          !isRecord(body) ||
          typeof body.preview !== "string" ||
          typeof body.sourceKey !== "string"
        ) {
          throw new Error("transform request is missing preview/source");
        }
        const sourceKey = body.sourceKey;
        if (sourceKey.includes(image.fileName)) {
          if (body.preview === "animation") {
            throw new Error("image must never request an animation");
          }
          req.reply({
            statusCode: 202,
            body: { jobId: imageJobId, status: "pending" },
          });
          return;
        }
        if (sourceKey.includes(pdf.fileName)) {
          if (body.preview === "animation") {
            throw new Error("pdf must never request an animation");
          }
          req.reply({ statusCode: 500, body: { message: "preview failed" } });
          return;
        }
        req.continue();
      }).as("transform");
      cy.intercept(
        "GET",
        `/api/jobs/${imageJobId}`,
        completedPosterJob(imageJobId, imagePath),
      );

      openTiles();
      tile(image.fileName).scrollIntoView();
      tile(pdf.fileName).scrollIntoView();

      assertImageLoaded(image.fileName, "dStorage_thumbnail_image", imagePath);
      // Hovering an image or PDF must never request an animation preview.
      hoverEnter(image.fileName);
      hoverLeave(image.fileName);
      hoverEnter(pdf.fileName);

      cy.get("@transform.all").should((interceptions) => {
        expect(
          previewOf(interceptions, "animation", image.fileName),
          "images never request animation",
        ).to.have.length(0);
        expect(
          previewOf(interceptions, "animation", pdf.fileName),
          "pdfs never request animation",
        ).to.have.length(0);
      });
    });
  });
});

// Generated by Cypress Author on 2026-10-12
//
// Deterministic coverage for the stable multi-phase thumbnail preview progress
// feature (spec: .kiro/specs/stable-thumbnail-preview-progress). These
// scenarios drive the full animation lifecycle — initial indeterminate wait,
// determinate frame generation, indeterminate encoding, browser image
// download/decode, ready, and failure — through closure-controlled job and
// image responses, and verify geometry stability, text-free accessible
// semantics, quiet failure fallback, and keyboard/touch activation. Phase
// edges are forced with controllable mutable state, never wall-clock waits.

// A controllable job endpoint. The test flips `current` between responses and
// each poll returns the latest value, so a single interceptor advances the
// lifecycle deterministically from pending -> frames -> encoding -> completed
// / failed exactly when the test chooses.
type JobResponse =
  | { kind: "pending" }
  | {
      kind: "running";
      phase: "frames" | "encoding";
      completed: number;
      total: number;
    }
  | { kind: "completed"; url: string }
  | { kind: "failed"; httpStatus: number; message: string };

function jobBody(
  jobId: string,
  response: JobResponse,
): Record<string, unknown> {
  switch (response.kind) {
    case "pending":
      return { jobId, status: "pending" };
    case "running":
      return {
        jobId,
        status: "running",
        progress: {
          phase: response.phase,
          completed: response.completed,
          total: response.total,
        },
      };
    case "completed":
      return {
        jobId,
        status: "completed",
        httpStatus: 200,
        result: { url: response.url, contentType: "image/jpeg" },
      };
    case "failed":
      return {
        jobId,
        status: "failed",
        httpStatus: response.httpStatus,
        error: { message: response.message },
      };
  }
}

// Fake only setTimeout/clearTimeout. rAF must stay real (the latest-active
// coordinator promotes via requestAnimationFrame) and Date/intervals must
// stay real for Clerk. Install AFTER setup so no page load sees the clock.
function installTimerClock() {
  cy.clock(0, ["setTimeout", "clearTimeout"]);
}

// cy.wait("@alias") resolves when Cypress sends the response, not when the
// app has handled it, so a timer the app schedules in reaction (TanStack's
// retry, notifyManager's setTimeout(cb, 0)) may not exist yet when the next
// cy.tick runs. Tick `ms`, give the app a short real-time window to react,
// and repeat until `done` holds. Bounded so a real regression still fails.
function tickUntil(
  ms: number,
  done: () => Cypress.Chainable<boolean>,
  label: string,
  attempt = 0,
): void {
  cy.tick(ms, { log: false });
  cy.wait(50, { log: false });
  done().then((reached) => {
    if (reached) return;
    if (attempt >= 40) {
      throw new Error(`tickUntil(${ms}) never reached: ${label}`);
    }
    tickUntil(ms, done, label, attempt + 1);
  });
}

// Dispatch a real touch PointerEvent sequence. React Aria's useLongPress
// listens to pointerdown/pointerup with pointerType "touch" and schedules its
// threshold with global setTimeout on pointerdown. The hold duration is
// advanced with cy.tick() on the late, narrow clock from installTimerClock()
// (setTimeout/clearTimeout only, installed after setup), so 499ms vs 500ms is
// exact.
function touchDown(fileName: string) {
  tile(fileName).find("[data-cy='dStorage_thumbnail']").trigger("pointerdown", {
    eventConstructor: "PointerEvent",
    pointerType: "touch",
    pointerId: 1,
    button: 0,
    bubbles: true,
  });
}

function touchUp(fileName: string) {
  tile(fileName).find("[data-cy='dStorage_thumbnail']").trigger("pointerup", {
    eventConstructor: "PointerEvent",
    pointerType: "touch",
    pointerId: 1,
    button: 0,
    bubbles: true,
  });
}

function keyboardFocus(fileName: string) {
  tile(fileName).find("[data-cy='dStorage_thumbnail']").focus();
}

function keyboardBlur(fileName: string) {
  tile(fileName).find("[data-cy='dStorage_thumbnail']").blur();
}

// Capture the thumbnail and enclosing tile border-box rectangles so a later
// assertion can prove no lifecycle state changed the geometry.
function recordBox(fileName: string, alias: string) {
  tile(fileName)
    .find("[data-cy='dStorage_thumbnail']")
    .then(($thumb) => {
      const node = $thumb[0];
      if (!node) {
        throw new Error("thumbnail element not found");
      }
      const thumb = node.getBoundingClientRect();
      const item = node.closest("[data-cy='dStorage_item']") as HTMLElement;
      const tileRect = item.getBoundingClientRect();
      cy.wrap({
        tw: thumb.width,
        th: thumb.height,
        iw: tileRect.width,
        ih: tileRect.height,
      }).as(alias);
    });
}

function assertBoxUnchanged(fileName: string, alias: string, label: string) {
  cy.get<{ tw: number; th: number; iw: number; ih: number }>(`@${alias}`).then(
    (before) => {
      tile(fileName)
        .find("[data-cy='dStorage_thumbnail']")
        .then(($thumb) => {
          const node = $thumb[0];
          if (!node) {
            throw new Error("thumbnail element not found");
          }
          const thumb = node.getBoundingClientRect();
          const item = node.closest("[data-cy='dStorage_item']") as HTMLElement;
          const tileRect = item.getBoundingClientRect();
          expect(thumb.width, `${label} thumbnail width`).to.eq(before.tw);
          expect(thumb.height, `${label} thumbnail height`).to.eq(before.th);
          expect(tileRect.width, `${label} tile width`).to.eq(before.iw);
          expect(tileRect.height, `${label} tile height`).to.eq(before.ih);
        });
    },
  );
}

describe("stable thumbnail preview progress", () => {
  beforeEach(() => {
    cy.viewport(1440, 900);
  });

  // Task 1 + Task 3: initial indeterminate -> determinate frames -> encoding
  // indeterminate, with geometry stability and no visible text.
  it("drives initial wait → frames → encoding with a stable, text-free top rail", () => {
    cy.uniqueRecordName("phases").then((marker) => {
      const video = namedFixture(VIDEO_A, marker);
      const posterPath = "/mock-thumbs/phases-poster.jpg";
      const posterJobId = "11111111-aaaa-4aaa-8aaa-aaaaaaaaaaa1";
      const animationJobId = "11111111-aaaa-4aaa-8aaa-aaaaaaaaaaa2";
      const jobState = { current: { kind: "pending" } as JobResponse };

      signInAndOpenDrive();
      uploadThroughDialog([video]);
      serveImage(posterPath);
      routeTransform(
        [{ includes: video.fileName, posterJobId, animationJobId }],
        "transform",
      );
      cy.intercept("GET", /\/api\/jobs\//, (req) => {
        const jobId = req.url.split("/").pop() ?? "";
        if (jobId === posterJobId) {
          req.reply(completedPosterJob(posterJobId, posterPath));
          return;
        }
        if (jobId === animationJobId) {
          req.reply({
            statusCode: 200,
            body: jobBody(jobId, jobState.current),
          });
          return;
        }
        req.continue();
      }).as("job");

      openTiles();
      tile(video.fileName).scrollIntoView();
      assertImageLoaded(video.fileName, "dStorage_thumbnail_image", posterPath);
      recordBox(video.fileName, "phasesBox");

      // Activate: the first phase is an indeterminate rail (no numeric ARIA).
      hoverEnter(video.fileName);
      tile(video.fileName)
        .find("[role='progressbar']", { timeout: LONG })
        .should("have.attr", "data-rail-state", "indeterminate")
        .and("not.have.attr", "aria-valuenow");
      assertBoxUnchanged(video.fileName, "phasesBox", "initial-wait");

      // Frames: determinate, exact current/min/max and value text.
      cy.then(() => {
        jobState.current = {
          kind: "running",
          phase: "frames",
          completed: 3,
          total: 6,
        };
      });
      tile(video.fileName)
        .find("[role='progressbar']", { timeout: LONG })
        .should("have.attr", "data-rail-state", "frames")
        .and("have.attr", "aria-valuenow", "3")
        .and("have.attr", "aria-valuemin", "0")
        .and("have.attr", "aria-valuemax", "6")
        .and("have.attr", "aria-valuetext", "3 of 6 frames");
      assertBoxUnchanged(video.fileName, "phasesBox", "frames");

      // Encoding: back to indeterminate (no aria-valuenow).
      cy.then(() => {
        jobState.current = {
          kind: "running",
          phase: "encoding",
          completed: 6,
          total: 6,
        };
      });
      tile(video.fileName)
        .find("[role='progressbar']", { timeout: LONG })
        .should("have.attr", "data-rail-state", "indeterminate")
        .and("not.have.attr", "aria-valuenow");
      assertBoxUnchanged(video.fileName, "phasesBox", "encoding");

      // No visible numeric/percent/phase text anywhere in the rail.
      tile(video.fileName)
        .find("[data-cy='dStorage_thumbnail_progress']")
        .invoke("text")
        .should("match", /^\s*$/);

      // The rail is a 2px top-aligned absolute overlay.
      tile(video.fileName)
        .find("[data-cy='dStorage_thumbnail_progress']")
        .then(($rail) => {
          const rail = $rail[0] as HTMLElement;
          const style = getComputedStyle(rail);
          expect(style.position, "rail position").to.eq("absolute");
          expect(
            Math.round(rail.getBoundingClientRect().height),
            "rail height",
          ).to.eq(2);
          const thumb = rail.closest(
            "[data-cy='dStorage_thumbnail']",
          ) as HTMLElement;
          expect(
            Math.round(rail.getBoundingClientRect().top),
            "rail top aligns with thumbnail top",
          ).to.eq(Math.round(thumb.getBoundingClientRect().top));
        });
    });
  });

  // Task 2: poster remains visible through download/decode; animation only
  // revealed after a genuine load, and the rail disappears at ready.
  it("keeps the poster visible until the animation loads, then reveals it and removes the rail", () => {
    cy.uniqueRecordName("ready").then((marker) => {
      const video = namedFixture(VIDEO_A, marker);
      const posterPath = "/mock-thumbs/ready-poster.jpg";
      const animationPath = "/mock-thumbs/ready-animation.jpg";
      const posterJobId = "22222222-aaaa-4aaa-8aaa-aaaaaaaaaaa1";
      const animationJobId = "22222222-aaaa-4aaa-8aaa-aaaaaaaaaaa2";

      signInAndOpenDrive();
      uploadThroughDialog([video]);
      serveImage(posterPath);
      // Delay the animation image so there is a window where the server has
      // returned a URL but the browser has not finished loading it.
      serveImage(animationPath, 800);
      routeTransform(
        [{ includes: video.fileName, posterJobId, animationJobId }],
        "transform",
      );
      cy.intercept("GET", /\/api\/jobs\//, (req) => {
        const jobId = req.url.split("/").pop() ?? "";
        if (jobId === posterJobId) {
          req.reply(completedPosterJob(posterJobId, posterPath));
          return;
        }
        if (jobId === animationJobId) {
          req.reply(completedPosterJob(animationJobId, animationPath));
          return;
        }
        req.continue();
      }).as("job");

      openTiles();
      tile(video.fileName).scrollIntoView();
      assertImageLoaded(video.fileName, "dStorage_thumbnail_image", posterPath);
      hoverEnter(video.fileName);

      // While the animation downloads, the poster image stays loaded and
      // visible and the final-wait rail is present.
      tile(video.fileName)
        .find("[data-cy='dStorage_thumbnail_image']")
        .should("have.attr", "src")
        .and("include", posterPath);

      // After genuine load + decode, the animation is revealed and the rail is
      // removed.
      assertImageLoaded(
        video.fileName,
        "dStorage_thumbnail_animation",
        animationPath,
      );
      tile(video.fileName)
        .find("[role='progressbar']", { timeout: LONG })
        .should("not.exist");
    });
  });

  // Task 4: a failed animation job quietly restores the poster, shows a brief
  // failure rail, and dismisses it by timer without an animationend event.
  it("shows a brief failure rail then restores the poster when the animation job fails", () => {
    cy.uniqueRecordName("failrail").then((marker) => {
      const video = namedFixture(VIDEO_A, marker);
      const posterPath = "/mock-thumbs/failrail-poster.jpg";
      const posterJobId = "33333333-aaaa-4aaa-8aaa-aaaaaaaaaaa1";
      const animationJobId = "33333333-aaaa-4aaa-8aaa-aaaaaaaaaaa2";

      signInAndOpenDrive();
      uploadThroughDialog([video]);
      serveImage(posterPath);
      routeTransform(
        [{ includes: video.fileName, posterJobId, animationJobId }],
        "transform",
      );
      cy.intercept(
        "GET",
        `/api/jobs/${posterJobId}`,
        completedPosterJob(posterJobId, posterPath),
      );
      cy.intercept("GET", `/api/jobs/${animationJobId}`, {
        statusCode: 200,
        body: jobBody(animationJobId, {
          kind: "failed",
          httpStatus: 504,
          message: "Image processing timed out",
        }),
      }).as("animationJob");

      openTiles();
      tile(video.fileName).scrollIntoView();
      assertImageLoaded(video.fileName, "dStorage_thumbnail_image", posterPath);

      // Setup ran under real time. Fake only setTimeout/clearTimeout from here
      // so the dismissal timer is driven solely by cy.tick.
      installTimerClock();
      hoverEnter(video.fileName);

      // First failed job GET. The animation query has retry: 1 with the default
      // 1000ms delay, so it schedules a fake retry timer instead of failing.
      cy.wait("@animationJob");
      // Fire the retry: second transform POST and job GET. If the app had not
      // yet scheduled the retry when the first tick ran, the next 1000ms tick
      // fires it. Advancing extra here is harmless: the dismissal timer does
      // not exist until the second failure is delivered.
      tickUntil(
        1000,
        () =>
          cy
            .get<{ request: { body?: unknown } }[]>("@transform.all", {
              log: false,
            })
            .then(
              (interceptions) =>
                previewOf(interceptions, "animation", video.fileName).length >=
                2,
            ),
        "animation retry POST",
      );
      cy.wait("@animationJob");
      // TanStack's notifyManager delivers the error via setTimeout(cb, 0),
      // which may be scheduled only after the browser handles the response.
      // Flush with 0ms ticks (no fake time passes, so the 999/1000 contract
      // below stays exact) until the effect calls failAttempt and the failed
      // rail renders. Its 1000ms dismissal timer then starts at a known time.
      tickUntil(
        0,
        () =>
          tile(video.fileName).then(
            ($tile) =>
              $tile.find(
                "[data-cy='dStorage_thumbnail_progress'][data-rail-state='failed']",
              ).length > 0,
          ),
        "failed rail",
      );

      // A failure status rail appears (role=status, error state) with no value.
      tile(video.fileName)
        .find(
          "[data-cy='dStorage_thumbnail_progress'][data-rail-state='failed']",
          {
            timeout: LONG,
          },
        )
        .should("exist")
        .and("not.have.attr", "aria-valuenow");

      // The poster remains throughout.
      tile(video.fileName)
        .find("[data-cy='dStorage_thumbnail_image']")
        .should("have.attr", "src")
        .and("include", posterPath);

      // Still present just before the 1000ms dismissal timer.
      cy.tick(999);
      tile(video.fileName)
        .find(
          "[data-cy='dStorage_thumbnail_progress'][data-rail-state='failed']",
        )
        .should("exist");

      // Dismissed by the timer alone, without any animationend.
      cy.tick(1);
      tile(video.fileName)
        .find("[data-cy='dStorage_thumbnail_progress']")
        .should("not.exist");
      tile(video.fileName)
        .find("[data-cy='dStorage_thumbnail_animation']")
        .should("not.exist");
    });
  });

  // Task 5: keyboard focus activates the preview; blur restores the poster.
  it("activates the animation while the thumbnail is keyboard-focused and stops on blur", () => {
    cy.uniqueRecordName("keyboard").then((marker) => {
      const video = namedFixture(VIDEO_A, marker);
      const posterPath = "/mock-thumbs/keyboard-poster.jpg";
      const animationPath = "/mock-thumbs/keyboard-animation.jpg";
      const posterJobId = "44444444-aaaa-4aaa-8aaa-aaaaaaaaaaa1";
      const animationJobId = "44444444-aaaa-4aaa-8aaa-aaaaaaaaaaa2";

      signInAndOpenDrive();
      uploadThroughDialog([video]);
      serveImage(posterPath);
      serveImage(animationPath);
      routeTransform(
        [{ includes: video.fileName, posterJobId, animationJobId }],
        "transform",
      );
      cy.intercept("GET", /\/api\/jobs\//, (req) => {
        const jobId = req.url.split("/").pop() ?? "";
        if (jobId === posterJobId) {
          req.reply(completedPosterJob(posterJobId, posterPath));
          return;
        }
        if (jobId === animationJobId) {
          req.reply(completedPosterJob(animationJobId, animationPath));
          return;
        }
        req.continue();
      }).as("job");

      openTiles();
      tile(video.fileName).scrollIntoView();
      assertImageLoaded(video.fileName, "dStorage_thumbnail_image", posterPath);

      // The surface is focusable with the expected accessible name.
      tile(video.fileName)
        .find("[data-cy='dStorage_thumbnail']")
        .should("have.attr", "aria-label", `Preview ${video.fileName}`)
        .and("have.attr", "tabindex", "0");

      keyboardFocus(video.fileName);
      cy.get("@transform.all", { timeout: LONG }).should((interceptions) => {
        expect(
          previewOf(interceptions, "animation", video.fileName).length,
          "focus requests an animation",
        ).to.be.greaterThan(0);
      });

      keyboardBlur(video.fileName);
      // After blur the poster is the visible layer and no progress persists.
      tile(video.fileName)
        .find("[data-cy='dStorage_thumbnail_image']")
        .should("have.attr", "src")
        .and("include", posterPath);
    });
  });

  // Task 5: touch press-and-hold activates only at the 500ms threshold and not
  // before, and does not select the row.
  it("activates on a 500ms touch hold but not at 499ms, and does not select the row", () => {
    cy.viewport("iphone-x");
    cy.uniqueRecordName("hold").then((marker) => {
      const video = namedFixture(VIDEO_A, marker);
      const posterPath = "/mock-thumbs/hold-poster.jpg";
      const animationPath = "/mock-thumbs/hold-animation.jpg";
      const posterJobId = "55555555-aaaa-4aaa-8aaa-aaaaaaaaaaa1";
      const animationJobId = "55555555-aaaa-4aaa-8aaa-aaaaaaaaaaa2";

      signInAndOpenDrive();
      uploadThroughDialog([video]);
      serveImage(posterPath);
      serveImage(animationPath);
      routeTransform(
        [{ includes: video.fileName, posterJobId, animationJobId }],
        "transform",
      );
      cy.intercept("GET", /\/api\/jobs\//, (req) => {
        const jobId = req.url.split("/").pop() ?? "";
        if (jobId === posterJobId) {
          req.reply(completedPosterJob(posterJobId, posterPath));
          return;
        }
        if (jobId === animationJobId) {
          req.reply(completedPosterJob(animationJobId, animationPath));
          return;
        }
        req.continue();
      }).as("job");

      openTiles();
      tile(video.fileName).scrollIntoView();
      assertImageLoaded(video.fileName, "dStorage_thumbnail_image", posterPath);

      // Guard: the row is selectable and currently unselected, so the
      // post-release "not selected" check cannot pass vacuously.
      tile(video.fileName).should("have.attr", "aria-selected", "false");

      // Setup ran under real time. Fake only setTimeout/clearTimeout from here
      // so the long-press threshold is driven solely by cy.tick.
      installTimerClock();

      // Hold for only 499ms then release: no animation request.
      touchDown(video.fileName);
      cy.tick(499);
      touchUp(video.fileName);
      cy.get("@transform.all").should((interceptions) => {
        expect(
          previewOf(interceptions, "animation", video.fileName),
          "no activation before 500ms",
        ).to.have.length(0);
      });

      // Hold through the 500ms threshold: the animation is requested.
      touchDown(video.fileName);
      cy.tick(500);
      cy.get("@transform.all", { timeout: LONG }).should((interceptions) => {
        expect(
          previewOf(interceptions, "animation", video.fileName).length,
          "activation at 500ms",
        ).to.be.greaterThan(0);
      });

      // Releasing the completed hold must not select the row.
      touchUp(video.fileName);
      tile(video.fileName)
        .should("not.have.attr", "aria-selected", "true")
        .and("not.have.attr", "data-selected");
    });
  });
});
